ht_ent_t t[16];
ht_init(t);
CHECK_EQ(ht_put(t, 42, 4242), 1);
int *v = ht_get(t, 42);
CHECK_NOT_NULL(v);
CHECK_EQ(*v, 4242);

ht_ent_t t[16];
ht_init(t);
int h = (int)(((unsigned)7 * 2654435761u) % 16);
CHECK_EQ(ht_put(t, 7, 1), 1);
CHECK_EQ(ht_put(t, 7 + 16, 2), 1);
CHECK_EQ(*ht_get(t, 7), 1);
CHECK_EQ(*ht_get(t, 7 + 16), 2);

ht_ent_t t[16];
ht_init(t);
int h = (int)(((unsigned)3 * 2654435761u) % 16);
CHECK_EQ(ht_put(t, 3, 1), 1);
CHECK_EQ(ht_put(t, 3 + 16, 2), 1);
CHECK_EQ(ht_del(t, 3), 1);
CHECK_EQ(ht_put(t, 3 + 32, 3), 1);
CHECK_EQ(*ht_get(t, 3 + 32), 3);
CHECK_NULL(ht_get(t, 3));

ht_ent_t t[16];
ht_init(t);
int put_all = 1;
for (int k = 0; k < 16; k++) put_all &= ht_put(t, k, k);
CHECK_EQ(put_all, 1);
CHECK_EQ(ht_put(t, 100, 1), 0);
